dren\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"The Supreme Personality of Godhead said: My dear Arjuna, O son of Pṛthā, see now My opulences, hundreds of thousands of varied divine and multicolored forms.\"}}]}]}]]]}]\n2e:[\"$\",\"div\",\"3151-purport,3151-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L29\",\"child-3156\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Arjuna wanted to see Kṛṣṇa in His universal form, which, although a transcendental form, is just manifested for the cosmic manifestation and is therefore subject to the temporary time of this material nature. As the material nature is manifested and not manifested, similarly this universal form of Kṛṣṇa is manifested and nonmanifested. It is not eternally situated in the spiritual sky like Kṛṣṇa’s other forms. As far as a devotee is concerned, he is not eager to see the universal form, but because Arjuna wanted to see Kṛṣṇa in this way, Kṛṣṇa reveals this form. This universal form is not possible to be seen by any ordinary man. Kṛṣṇa must give one the power to see it.\"}}]}]]]}]\n33:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"26:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundaraj